 * Token-bucket rate limiter with a FIFO fairness queue.
 *
 * - `capacity`: maximum burst size (bucket size).
 * - `refillPerSec`: continuous refill rate in tokens per second
 *   (fractional/continuous math, not fixed windows).
 *
 * Calls that find the bucket empty are queued FIFO and dispatched as
 * tokens continuously accrue. A queued call may specify a `timeoutMs`;
 * if it waits longer than that it rejects with a TimeoutError (no token
 * is consumed or freed by a timeout). `cancelAll()` rejects every queued
 * call immediately.
 */

export class TimeoutError extends Error {
  constructor(message = 'Rate limiter: timed out waiting for a token') {
    super(message);
    this.name = 'TimeoutError';
  }
}

export class CancelledError extends Error {
  constructor(message = 'Rate limiter: cancelled while queued') {
    super(message);
    this.name = 'CancelledError';
  }
}

export interface LimiterOptions {
  capacity: number;
  refillPerSec: number;
}

export interface CallOptions {
  /** Max time (ms) a call may spend queued waiting for a token. */
  timeoutMs?: number;
}

export interface Stats {
  /** Whole tokens currently in the bucket (fractional part truncated). */
  available: number;
  /** Number of calls waiting in the FIFO queue. */
  queued: number;
}

interface QueuedCall<T = unknown> {
  fn: () => T | Promise<T>;
  resolve: (value: T) => void;
  reject: (err: unknown) => void;
  timer: ReturnType<typeof setTimeout> | null;
}

/** Tolerance for floating-point drift in the continuous refill math. */
const EPS = 1e-9;

export type RateLimiter = {
  /**
   * Run `fn` under the rate limit. Consumes one token; queues FIFO when
   * the bucket is empty. Rejects with TimeoutError if queued longer than
   * `opts.timeoutMs`.
   */
  <T>(fn: () => T | Promise<T>, opts?: CallOptions | number): Promise<T>;
  /** Wrap an async function so every invocation is rate limited. */
  wrap<F extends (...args: never[]) => unknown>(
    fn: F,
  ): (...args: Parameters<F>) => Awaited<ReturnType<F>>;
  /** Current bucket level (whole tokens) and queue depth. */
  stats(): Stats;
  /** Reject everything currently queued; running calls are unaffected. */
  cancelAll(reason?: Error): void;
};

export function createLimiter({
  capacity,
  refillPerSec,
}: LimiterOptions): RateLimiter {
  if (!Number.isFinite(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive number');
  }
  if (!Number.isFinite(refillPerSec) || refillPerSec <= 0) {
    throw new RangeError('refillPerSec must be a positive number');
  }

  let tokens = capacity;
  let lastRefill = Date.now();
  const queue: QueuedCall[] = [];
  let refillTimer: ReturnType<typeof setTimeout> | null = null;

  /** Accrue tokens continuously since the last refill checkpoint. */
  function refill(): void {
    const t = Date.now();
    const elapsedMs = t - lastRefill;
    if (elapsedMs > 0) {
      tokens = Math.min(capacity, tokens + (elapsedMs / 1000) * refillPerSec);
      lastRefill = t;
    }
  }

  function clearRefillTimer(): void {
    if (refillTimer !== null) {
      clearTimeout(refillTimer);
      refillTimer = null;
    }
  }

  function clearCallTimer(call: QueuedCall): void {
    if (call.timer !== null) {
      clearTimeout(call.timer);
      call.timer = null;
    }
  }

  function dispatch(call: QueuedCall): void {
    Promise.resolve()
      .then(call.fn)
      .then(call.resolve, call.reject);
  }

  /** Arm the timer for the moment the next queued call can start. */
  function scheduleRefill(): void {
    clearRefillTimer();
    if (queue.length === 0) return;
    const deficit = 1 - tokens;
    if (deficit <= EPS) {
      // Should be unreachable (pump drains greedily), kept as a safeguard.
      pump();
      return;
    }
    const delayMs = Math.ceil(((deficit / refillPerSec) * 1000) - EPS * 1000);
    refillTimer = setTimeout(pump, Math.max(delayMs, 1));
  }

  /** Drain the queue as far as current tokens allow, then re-arm. */
  function pump(): void {
    clearRefillTimer();
    refill();
    while (queue.length > 0 && tokens >= 1 - EPS) {
      tokens = Math.max(0, tokens - 1);
      const call = queue.shift() as QueuedCall;
      clearCallTimer(call);
      dispatch(call);
    }
    scheduleRefill();
  }

  function limit<T>(
    fn: () => T | Promise<T>,
    opts?: CallOptions | number,
  ): Promise<T> {
    const timeoutMs =
      typeof opts === 'number' ? opts : (opts?.timeoutMs ?? undefined);

    return new Promise<T>((resolve, reject) => {
      refill();

      // Fast path: token available and nobody queued (FIFO is preserved).
      if (queue.length === 0 && tokens >= 1 - EPS) {
        tokens = Math.max(0, tokens - 1);
        Promise.resolve()
          .then(fn)
          .then(resolve, reject);
        return;
      }

      const call: QueuedCall<T> = { fn, resolve, reject, timer: null };

      if (timeoutMs !== undefined) {
        call.timer = setTimeout(() => {
          const idx = queue.indexOf(call as QueuedCall);
          if (idx !== -1) queue.splice(idx, 1);
          call.timer = null;
          // Rejecting a timed-out call neither consumes nor frees a token.
          reject(new TimeoutError());
        }, timeoutMs);
      }

      queue.push(call as QueuedCall);
      scheduleRefill();
    });
  }

  function wrap<F extends (...args: never[]) => unknown>(
    fn: F,
  ): (...args: Parameters<F>) => Awaited<ReturnType<F>> {
    return (...args: Parameters<F>) =>
      limit(() => fn(...args) as Awaited<ReturnType<F>>);
  }

  function stats(): Stats {
    refill();
    return {
      available: Math.min(capacity, Math.floor(tokens + EPS)),
      queued: queue.length,
    };
  }

  function cancelAll(reason?: Error): void {
    const pending = queue.splice(0, queue.length);
    clearRefillTimer();
    for (const call of pending) {
      clearCallTimer(call);
      call.reject(reason ?? new CancelledError());
    }
  }

  return Object.assign(limit, { wrap, stats, cancelAll });
}
