    const started: string[] = [];
    const results: Array<{ name: string; doneAt: number }> = [];
    const limited = createLimiter({ capacity: 1, refillPerSec: 10 }); // 100ms per token

    const enqueue = (name: string) =>
      limited(async () => {
        started.push(name);
        return name;
      }).then((name) => {
        results.push({ name, doneAt: Date.now() });
        return name;
      });

    const all = ['first', 'second', 'third', 'fourth'].map(enqueue);

    expect(limited.stats()).toEqual({ available: 0, queued: 3 });
    await vi.advanceTimersByTimeAsync(0);
    expect(started).toEqual(['first']);

    await vi.advanceTimersByTimeAsync(300);
    await Promise.all(all);

    // Starts happen strictly in enqueue order despite staggered refills...
    expect(started).toEqual(['first', 'second', 'third', 'fourth']);
    // ...and completions resolve in FIFO order too (~100ms apart).
    expect(results.map((r) => r.name)).toEqual([
      'first',
      'second',
      'third',
      'fourth',
    ]);
    for (let i = 1; i < results.length; i++) {
